  const toolsSchema={type:'object',properties:{answer:{type:'string',description:'给用户的答复，说明待确认条目或回答记录问题'},records:{type:'array',items:{type:'object',properties:{type:{type:'string',enum:['learning','work','work_note','idea','experience']},date:{type:'string',description:'yyyy-MM-dd'},title:{type:'string'},occurredAt:{type:'string',description:'灵感或经验发生时间，本地 yyyy-MM-ddTHH:mm:ss；date须一致'},platform:{type:'string'},contentType:{type:'string',enum:['article','video','course','book','other']},tags:{type:'array',items:{type:'string'}},note:{type:'string'},url:{type:'string'},durationMinutes:{type:'number'},masteryLevel:{type:'string',enum:['unspecified','beginner','familiar','proficient']},evidenceType:{type:'string',enum:['none','self','practice','tested']},evidenceNote:{type:'string'},workStart:{type:'string',description:'本地 ISO 日期时间 yyyy-MM-ddTHH:mm:ss'},workEnd:{type:'string'},breaks:{type:'array',items:{type:'object',properties:{start:{type:'string'},end:{type:'string'}},required:['start','end']}}},required:['type','date','title','durationMinutes']}},citations:{type:'array',items:{type:'string'},description:'只引用上下文中实际存在的记录 id'}},required:['answer','records','citations']};
