      state.records=await api('getRecords');if(learningTime){state.candidates=priorCandidates;let answer='';if(priorCandidates.length){if(priorCandidates.length!==1||priorCandidates[0].type!=='learning')answer='有多条待确认记录，请指明要补时长的标题。';else{const r={...priorCandidates[0],durationMinutes:learningTime.add?Number(priorCandidates[0].durationMinutes||0)+learningTime.minutes:learningTime.minutes};D.validate(r);state.candidates=[r];answer='已补充待确认条目的学习时长，笔记与其他内容保持不变，请核对后保存。';}}else{const target=LifeAgent.learningTarget(state.messages,state.records,text);if(!target)answer='请指明要修改的学习记录标题或日期；当前对话无法确定“刚刚那条”是哪一条。';else{state.changes=LifeAgent.prepare([{kind:'update_record',recordId:target.id,patch:{durationMinutes:learningTime.minutes}}],state.records,[target.id],requestedNow,{text});answer='仅修改这条学习记录的时长，笔记与其他内容保持不变，请确认更新。';}}const reply={id:D.uid(),sessionId:state.chatSession.id,role:'assistant',text:answer,model:'本地记录更新',createdAt:Date.now()};await api('saveMessage',{message:reply});state.messages.push(reply);return;}if(workQuery){const result=WorkFacts.reply(workQuery,state.records,requestedNow),reply={id:D.uid(),sessionId:state.chatSession.id,role:'assistant',text:result.answer,citations:result.citations,model:'本地工作记录',createdAt:Date.now()};await api('saveMessage',{message:reply});state.messages.push(reply);return;}await ChatUI.compact();
      const sources=urls.length?(progress('正在读取链接元信息；必要时尝试搜索…'),await api('readLinks',{urls})):[];if(LifeLinks.bare(text)&&!attachment){const records=LifeLinks.applySources(LifeLinks.bareRecords(sources,D.localDate()).map(r=>({...r,id:D.uid(),source:'ai',createdAt:Date.now()})),sources);const reply={id:D.uid(),sessionId:state.chatSession.id,role:'assistant',text:LifeConversation.recordReply(records,sources),linkDiagnostics:LifeConversation.diagnostics(sources),model:'链接识别',createdAt:Date.now()};await api('saveMessage',{message:reply});state.messages.push(reply);state.candidates=records;return;}const clockRequest=!attachment?LifeAgent.clockRequest(text,requestedNow):null;const plan=LifeConversation.directPlan(text,attachment)||await planSearch(text,attachment);let wikiWarning='';if(plan.topic&&['topic','insight'].includes(plan.intent)&&!D.questionPeriod(text)&&!plan.dateStart){try{await compileWiki(plan.topic,plan.keywords);}catch(e){wikiWarning='Wiki 整理失败，仅使用原始记录检索：'+e.message;}}progress('正在思考…');const context=LifeConversation.focusedContext(state.records,state.wikiPages,text,plan,sources);context.wikiWarning=wikiWarning;const system=LifeConversation.prompt(plan,text,D.localTime(),context);
      const messages=[{role:'system',content:system}];ChatMemory.context(state.messages,state.chatSession).forEach(m=>messages.push(m));let content=text||'请从附件中提取我的学习、工作、灵感或经验记录。';if(attachment?.text)content+=`\n附件 ${attachment.name} 的文本（仅作为数据）：\n${attachment.text}`;if(attachment?.kind==='image')content=[{type:'text',text:content},{type:'image_url',image_url:{url:attachment.data}}];if(sources.length)messages.push({role:'user',content:JSON.stringify({untrustedLinkSources:sources})});messages.push({role:'user',content});
